import{_ as e,o as r,c as s,a7 as o,ac as i,ai as a}from"./chunks/framework.2VKVf7rX.js";const m=JSON.parse('{"title":"MusicFly 客户端","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"music-fly.md","filePath":"music-fly.md"}'),d={name:"music-fly.md"};function l(n,t,c,h,g,u){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="musicfly-客户端" tabindex="-1">MusicFly 客户端 <a class="header-anchor" href="#musicfly-客户端" aria-label="Permalink to “MusicFly 客户端”">​</a></h1><p>相关文档：<a href="/music-free-site/feature.html">功能特性</a> · <a href="/music-free-site/music.html">音乐管理</a> · <a href="/music-free-site/changelog.html">发布日志</a></p><p><strong>MusicFly（乐记）</strong> 是 MusicFree 的官方客户端，基于 Flutter 编写，覆盖 <strong>Windows、macOS、Android、iOS、鸿蒙</strong>。它通过 MusicFree 的 HTTP / OpenSubsonic 接口连接你自己的服务器，浏览曲库、播放音乐并显示歌词；浏览器访问与第三方 Subsonic 客户端仍然可用，MusicFly 只是多了一个更贴合手机与桌面的入口。</p><p><img src="'+i+'" alt=""></p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h2><p>下载地址：<strong><a href="https://github.com/AnsGoo/music-fly/releases" target="_blank" rel="noreferrer">github.com/AnsGoo/music-fly/releases</a></strong>（也可从源码自行构建，仓库见 <a href="https://github.com/AnsGoo/music-fly" target="_blank" rel="noreferrer">AnsGoo/music-fly</a>）</p><table tabindex="0"><thead><tr><th>平台</th><th>安装包</th><th>说明</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><code>MusicFly-&lt;版本&gt;-windows-x64-setup.exe</code> / <code>-windows-x64.zip</code></td><td>安装版装到当前用户目录，无需管理员权限；zip 为免安装版</td></tr><tr><td><strong>macOS</strong></td><td><code>MusicFly-&lt;版本&gt;-macos.dmg</code></td><td>拖入「应用程序」即可</td></tr><tr><td><strong>Android</strong></td><td><code>musicfly-android-v&lt;版本&gt;.apk</code></td><td>直接安装；<code>.aab</code> 供应用商店分发使用</td></tr><tr><td><strong>iOS</strong></td><td><code>musicfly-ios-v&lt;版本&gt;-unsigned.zip</code></td><td>未签名包，需自行签名后安装</td></tr><tr><td><strong>鸿蒙</strong></td><td><code>musicfly-harmony-v&lt;版本&gt;-unsigned.hap</code></td><td>未签名包，需签名后在开发者模式安装</td></tr></tbody></table><p>各平台安装要点：</p><ul><li><strong>Windows</strong>：安装版带开始菜单项、可选桌面快捷方式和卸载程序，安装界面支持中英文；免安装版解压后运行 <code>MusicFly/musicfly.exe</code>。首次运行如被 SmartScreen 拦截，选择「更多信息 → 仍要运行」。</li><li><strong>macOS</strong>：安装包为 ad-hoc 签名，拷贝到其他机器后首次打开需<strong>右键 → 打开</strong>（或在「系统设置 → 隐私与安全性」中允许）。</li><li><strong>Android</strong>：允许「安装未知来源应用」后安装 APK；Android 13+ 首次播放会请求通知权限，拒绝后暂停时锁屏媒体控制器会消失（可在系统设置中重新授予）。</li><li><strong>iOS</strong>：Release 提供的是未签名包，需要用自己的开发者证书签名后安装（Xcode、AltStore 等工具均可）。</li><li><strong>鸿蒙</strong>：Release 提供的是未签名 HAP，需用开发者证书签名，并在开发者模式下安装。</li></ul><h2 id="连接自己的服务器" tabindex="-1">连接自己的服务器 <a class="header-anchor" href="#连接自己的服务器" aria-label="Permalink to “连接自己的服务器”">​</a></h2><p>安装后打开应用，在「设置 → 服务器」中填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>服务器地址</td><td>局域网填 NAS 地址（如 <code>http://192.168.1.10:14533</code>）；外网填已做反向代理并带 HTTPS 的域名</td></tr><tr><td>账号</td><td>MusicFree 的登录账号（默认 <code>admin</code>，部署后请尽快修改）</td></tr><tr><td>密码</td><td>对应账号密码</td></tr></tbody></table><p>登录成功后会话保存在本地，下次打开直接进库。</p><p><strong>多地址自动切换</strong>：普通登录可添加多个备用地址（局域网 + 外网），App 每 2 分钟探测一次并优选延迟最低的地址；当前地址请求失败时会立即重新探测，在家走内网、出门自动切外网，不需要手动改配置。</p><blockquote><p>地址不要带 <code>/rest</code> 后缀，也不要填飞牛网关路径 <code>/app/musicfree</code> —— 那是浏览器入口，客户端请使用服务端地址与端口。</p></blockquote><h2 id="飞牛-fnid-登录" tabindex="-1">飞牛 FNID 登录 <a class="header-anchor" href="#飞牛-fnid-登录" aria-label="Permalink to “飞牛 FNID 登录”">​</a></h2><p>在已接入飞牛统一网关的 NAS 上（服务端 <strong>V1.2.7 及以上</strong>），可以直接用<strong>飞牛账号（FNID）</strong>登录，不必再单独记住 MusicFree 的账号密码：</p><ol><li>登录页选择「飞牛账号（FNID）」。</li><li>输入飞牛账号完成校验；首次使用需要完成过一次「NAS 账号 ↔ MusicFree 账号」绑定（未绑定时会引导输入一次应用账号密码），详见 <a href="/music-free-site/changelog.html#v1-2-7">发布日志 V1.2.7</a>。</li><li>绑定后客户端即可免密进入，播放、封面、下载凭证一并就绪。</li></ol><p>FNID 登录会把飞牛解析出的链路（内网 IP、公网 IPv4 / IPv6、统一网关、中继域名）保存为内部故障切换池：在家走内网，离开内网自动切到公网 / 网关 / 中继，设置页只显示当前连接的一条只读地址。开启两步验证（2FA）的账号，在设备未被信任前需要在「外网自动切换」里填一次动态码。</p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h2><p><img src="'+a+'" alt=""></p><ul><li><strong>浏览</strong>：歌曲、专辑、艺术家、歌单、收藏五个分区，滚动到底自动翻页，列表带专辑封面。</li><li><strong>搜索</strong>：关键词搜索歌曲，结果可直接加入播放队列。</li><li><strong>播放</strong>：队列上下首、拖动进度、音量调节，播放结束自动续下一首；坏源自动跳过并说明原因。</li><li><strong>后台播放</strong>：锁屏、切后台、拔耳机继续播放；Android 走前台服务 + MediaSession（通知栏 / 锁屏 / 蓝牙按键可控），iOS 与鸿蒙同样支持后台音频与锁屏控制。</li><li><strong>歌词</strong>：读取服务端内嵌歌词，LRC 逐行高亮并跟随播放进度。</li></ul><blockquote><p>MusicFly 消费的是<strong>已入库</strong>的曲库：远程搜索下载、在线试听、去重、刮削等运维能力仍在 Web 管理端（<code>/admin</code>）完成。</p></blockquote><h2 id="与服务端版本的关系" tabindex="-1">与服务端版本的关系 <a class="header-anchor" href="#与服务端版本的关系" aria-label="Permalink to “与服务端版本的关系”">​</a></h2><ul><li>MusicFly 可直接连接 <strong>V1.2.7 及后续版本</strong>的 MusicFree 服务端，升级服务端不需要重装客户端。</li><li>服务端保持默认端口 <code>14533</code> 即可，不需要为客户端做额外配置；飞牛原生应用用户可用 <code>https://&lt;NAS 域名或 IP&gt;/app/musicfree</code> 打开网页端，但客户端连接仍使用地址 + 端口。</li><li>外网访问请自行配置反向代理与 HTTPS，并保证 <code>/rest</code> 接口可访问。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><p><strong>Q：客户端提示连接失败 / 401？</strong><br> A：先确认地址与端口正确（不要填 <code>/rest</code>、不要填网关路径）、账号密码可用；再用浏览器访问 <code>http://&lt;地址&gt;:14533/rest/ping.view</code> 验证服务端是否可达。</p><p><strong>Q：局域网能连，出门就断？</strong><br> A：普通登录请在「设置 → 服务器」添加外网地址作为备用，App 会自动优选；FNID 登录会自动维护故障切换池，无需手动配置。</p><p><strong>Q：封面、字体显示不出来（404）？</strong><br> A：这是服务端旧版本在网关入口下的已知问题，升级到 <strong>V1.2.8</strong> 并强制刷新即可，详见 <a href="/music-free-site/changelog.html">发布日志 V1.2.8</a>。</p><p><strong>Q：能直接在客户端里搜歌下载吗？</strong><br> A：不能。客户端的定位是「听歌」，搜索下载与入库请在 Web 管理端 <code>/admin/music</code> 完成（支持 WASM 插件与 <a href="/music-free-site/lx-source.html">洛雪音源</a>）。</p><p><strong>Q：iOS / 鸿蒙安装包为什么是 unsigned？</strong><br> A：Release 未附带签名证书。iOS 需自行签名（Xcode / AltStore 等），鸿蒙需用开发者证书签名后在开发者模式安装。</p><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to “反馈”">​</a></h2><ul><li>客户端问题：<a href="https://github.com/AnsGoo/music-fly/issues" target="_blank" rel="noreferrer">music-fly Issues</a></li><li>服务端问题：<a href="/music-free-site/feedback.html">提交 Issue 规范</a></li></ul>',33)])])}const f=e(d,[["render",l]]);export{m as __pageData,f as default};
